ALTER TABLE public.company_customization ADD COLUMN IF NOT EXISTS customer_card_template_layout_data text DEFAULT '{"version":1,"templates":[{"name":"Teachers","configured":true,"background":{"red":239,"green":246,"blue":255}},{"name":"Business","configured":true,"background":{"red":255,"green":247,"blue":237}},{"name":"School","configured":true,"background":{"red":240,"green":253,"blue":244}},{"name":"Personal / Regular","configured":true,"background":{"red":250,"green":245,"blue":255}},{"name":"Template 5","configured":false,"background":{"red":255,"green":255,"blue":255}}]}' NOT NULL;
ALTER TABLE public.company_customization ALTER COLUMN customer_card_template_layout_data SET DEFAULT '{"version":1,"templates":[{"name":"Teachers","configured":true,"background":{"red":239,"green":246,"blue":255}},{"name":"Business","configured":true,"background":{"red":255,"green":247,"blue":237}},{"name":"School","configured":true,"background":{"red":240,"green":253,"blue":244}},{"name":"Personal / Regular","configured":true,"background":{"red":250,"green":245,"blue":255}},{"name":"Template 5","configured":false,"background":{"red":255,"green":255,"blue":255}}]}';
UPDATE public.company_customization SET customer_card_template_layout_data='{"version":1,"templates":[{"name":"Teachers","configured":true,"background":{"red":239,"green":246,"blue":255}},{"name":"Business","configured":true,"background":{"red":255,"green":247,"blue":237}},{"name":"School","configured":true,"background":{"red":240,"green":253,"blue":244}},{"name":"Personal / Regular","configured":true,"background":{"red":250,"green":245,"blue":255}},{"name":"Template 5","configured":false,"background":{"red":255,"green":255,"blue":255}}]}' WHERE BTRIM(COALESCE(customer_card_template_layout_data,''))='';
ALTER TABLE public.customer_types ADD COLUMN IF NOT EXISTS customer_card_template_slot integer DEFAULT 4 NOT NULL;
ALTER TABLE public.customer_types DROP CONSTRAINT IF EXISTS customer_types_card_template_slot_chk;
ALTER TABLE public.customer_types ADD CONSTRAINT customer_types_card_template_slot_chk CHECK (customer_card_template_slot BETWEEN 1 AND 5);
INSERT INTO public.customer_types(name,description,is_active,auto_print_sale_receipt,customer_card_template_slot) SELECT 'Teachers','Teacher customer accounts',true,true,1 WHERE NOT EXISTS (SELECT 1 FROM public.customer_types WHERE LOWER(BTRIM(name)) IN ('teacher','teachers'));
INSERT INTO public.customer_types(name,description,is_active,auto_print_sale_receipt,customer_card_template_slot) SELECT 'Business','Business customer accounts',true,true,2 WHERE NOT EXISTS (SELECT 1 FROM public.customer_types WHERE LOWER(BTRIM(name)) IN ('business','businesses'));
INSERT INTO public.customer_types(name,description,is_active,auto_print_sale_receipt,customer_card_template_slot) SELECT 'School','School customer accounts',true,true,3 WHERE NOT EXISTS (SELECT 1 FROM public.customer_types WHERE LOWER(BTRIM(name)) IN ('school','schools'));
INSERT INTO public.customer_types(name,description,is_active,auto_print_sale_receipt,customer_card_template_slot) SELECT 'Personal / Regular','Personal and regular customer accounts',true,true,4 WHERE NOT EXISTS (SELECT 1 FROM public.customer_types WHERE LOWER(BTRIM(name)) IN ('general','personal / regular','personal','regular'));
UPDATE public.customer_types SET customer_card_template_slot=1 WHERE LOWER(BTRIM(name)) IN ('teacher','teachers');
UPDATE public.customer_types SET customer_card_template_slot=2 WHERE LOWER(BTRIM(name)) IN ('business','businesses');
UPDATE public.customer_types SET customer_card_template_slot=3 WHERE LOWER(BTRIM(name)) IN ('school','schools');
UPDATE public.customer_types SET customer_card_template_slot=4 WHERE LOWER(BTRIM(name)) IN ('general','personal / regular','personal','regular');
ALTER TABLE public.customer_accounts ADD COLUMN IF NOT EXISTS customer_since integer;
ALTER TABLE public.customer_accounts DROP CONSTRAINT IF EXISTS customer_accounts_customer_since_chk;
ALTER TABLE public.customer_accounts ADD CONSTRAINT customer_accounts_customer_since_chk CHECK (customer_since IS NULL OR customer_since BETWEEN 1900 AND 9999);
UPDATE public.customer_accounts SET customer_since=EXTRACT(YEAR FROM COALESCE(created_at,CURRENT_TIMESTAMP))::integer WHERE customer_since IS NULL;
